#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply=[&](int x,int y){
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
        ops.push_back({x,y});
    };

    auto find_val=[&](int v)->int{
        for(int i=0;i<n;i++) if(p[i]==v) return i;
        return -1;
    };

    for(int i=0;i<n-1&&(int)ops.size()<4*n;i++){
        int j=find_val(i+1);
        if(j==i) continue;

        // Bring element from position j to position 0
        if(j>0){
            if(j<n-1){
                // op(j, n-1-j): swaps first j and last n-1-j, x+y=n-1<n ✓
                apply(j, n-1-j);
                // element was at start of "middle" (pos j), now it's at pos n-1-j
                // Actually: [0..j-1 | j..j | j+1..n-1] with x=j, y=n-1-j
                // Result: [j+1..n-1 | j | 0..j-1] → element at position n-1-j
                apply(n-1-j, 1); // brings element to position 0... let me check
                // [0..n-2-j | n-1-j | n-j..n-1] → [n-j..n-1 | n-1-j | 0..n-2-j]
                // element at n-1-j stays at position j... hmm
                // Just use: after first op element is at n-1-j. If n-1-j>0, apply(n-1-j,1) won't help directly.
                // Simpler: apply(j,1) puts element from j to position 1, then apply(1,n-2) puts pos 1 to 0? No.
            }
            // Fallback: bring to position 0 via (j, n-j-1) then handle
        }
        // Just use brute approach: rotate until in place
        j=find_val(i+1);
        while(j!=i&&(int)ops.size()<4*n){
            if(j>0&&j<n-1) apply(j,1);
            else if(j==n-1&&n>2) apply(1,1);
            j=find_val(i+1);
            if(j==0&&i>0&&i<n-1) apply(1,n-1-i);
            j=find_val(i+1);
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
